#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int w,h;cin>>w>>h;string line;getline(cin,line);vector<string>a(h);for(auto&s:a)getline(cin,s);vector<pair<int,int>>v;for(int i=0;i<h;++i)for(int j=0;j<w;++j)if(a[i][j]=='S'||a[i][j]=='A')v.push_back({i,j});int k=v.size(),dx[4]={1,-1,0,0},dy[4]={0,0,1,-1};vector<vector<int>>d(k,vector<int>(k,1e9));for(int z=0;z<k;++z){vector<vector<int>>ds(h,vector<int>(w,-1));queue<pair<int,int>>q;q.push(v[z]);ds[v[z].first][v[z].second]=0;while(!q.empty()){auto [x,y]=q.front();q.pop();for(int t=0;t<4;++t){int nx=x+dx[t],ny=y+dy[t];if(nx>=0&&nx<h&&ny>=0&&ny<w&&a[nx][ny]!='#'&&ds[nx][ny]<0)ds[nx][ny]=ds[x][y]+1,q.push({nx,ny});}}for(int j=0;j<k;++j)d[z][j]=ds[v[j].first][v[j].second];}vector<int>best(k,1e9),used(k);best[0]=0;int ans=0;for(int it=0;it<k;++it){int u=-1;for(int i=0;i<k;++i)if(!used[i]&&(u<0||best[i]<best[u]))u=i;used[u]=1;ans+=best[u];for(int j=0;j<k;++j)best[j]=min(best[j],d[u][j]);}cout<<ans<<'\n';}}
